actions.script:
organizationPartyId=null
def requested=ec.user.getPreference('ACTIVE_ORGANIZATION')
if(!requested || requested=='_NA_') return
if(ec.user.isInGroup('ADMIN')) {
    def party=ec.entity.find('mantle.party.Party').condition('partyId',requested).disableAuthz().one()
    def internal=ec.entity.find('mantle.party.PartyRole').condition('partyId',requested).condition('roleTypeId','OrgInternal').disableAuthz().count()
    if(party && party.disabled!='Y' && internal && ec.entity.find('mantle.party.Organization').condition('partyId',requested).disableAuthz().one()) organizationPartyId=requested
    return
}
def partyId=ec.user.userAccount?.partyId
if(!partyId) return
def scope=ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo').parameters([partyId:partyId]).disableAuthz().call()
if(requested==scope?.activeOrgId && (scope?.userOrgIds ?: []).contains(requested)) organizationPartyId=requested

valid=false;fields=[:]
try {
    def name=values.ruleName?.toString()?.trim()
    def action=values.actionType?.toString()
    def active=values.isActive==null ? 'Y' : values.isActive, stack=values.isStackable==null ? 'N' : values.isStackable
    if(!name || !(active in ['Y','N']) || !(stack in ['Y','N']) || !(action in ['PatDiscountPercent','PatDiscountAmount','PatFixedPrice','PatMarginPercent'])) throw new IllegalArgumentException()
    if(action=='PatMarginPercent' && active=='Y') {
        ec.message.addError('Margin on Cost cannot be activated until its approved cost calculation is implemented.');return
    }
    def amount=(values.actionValue==null || values.actionValue=='') ? null : values.actionValue as BigDecimal
    def cap=(values.maxDiscount==null || values.maxDiscount=='') ? null : values.maxDiscount as BigDecimal
    def floor=(values.minimumPrice==null || values.minimumPrice=='') ? null : values.minimumPrice as BigDecimal
    def priority=(values.priority==null || values.priority=='') ? 10 : Integer.valueOf(values.priority.toString())
    if(amount==null || amount<0 || (action=='PatDiscountPercent' && amount>100) || (cap!=null && cap<0) || (floor!=null && floor<0)) throw new IllegalArgumentException()
    def stamp={v -> v==null || v=='' ? null : (v instanceof java.sql.Timestamp ? v : ec.l10n.parseTimestamp(v.toString(),null))}
    def from=stamp(values.validFromDate), thru=stamp(values.validThruDate)
    if((values.validFromDate && !from) || (values.validThruDate && !thru) || (from && thru && thru.before(from))) throw new IllegalArgumentException()
    fields=[ruleName:name,description:values.description,priority:priority,isActive:active,isStackable:stack,actionType:action,actionValue:amount,maxDiscount:cap,minimumPrice:floor,validFromDate:from,validThruDate:thru]
    valid=true
} catch(Exception ignored) {ec.message.addError('Enter a rule name, valid action, nonnegative amounts, percentage from 0 to 100, Y/N flags and an ordered date range.')}

valid=false;fields=[:]
def scope=ec.service.sync().name('zenith.pricing.RuleServices.get#RuleOrganization').call()
if(!ec.user.isInGroup('ADMIN') && organizationPartyId!=scope.organizationPartyId){ec.message.addError('Condition references must belong to your active organization.');return}
try {
    def type=values.conditionTypeEnumId?.toString(), op=values.operator?.toString()?.trim() ?: 'equals'
    def value=values.fieldValue?.toString()?.trim(), upper=values.fieldValueTo?.toString()?.trim()
    def numeric=type in ['PctMinQuantity','PctMinAmount']
    def categorical=type in ['PctProduct','PctProductCategory','PctCustomerGroup','PctChannel','PctRegion','PctDayOfWeek']
    if(!value || !(numeric || categorical || type=='PctTimeRange')) throw new IllegalArgumentException()
    def allowed=numeric ? ['equals','not-equals','greater-than','less-than','in','between'] : type=='PctTimeRange' ? ['equals','not-equals'] : ['equals','not-equals','in']
    if(!(op in allowed)) throw new IllegalArgumentException()
    def tokens=value.split(',',-1).collect{it.trim()}
    if(tokens.any{!it}) throw new IllegalArgumentException()
    if(numeric) {
        def numbers=(op=='in' ? tokens : [value]).collect{it as BigDecimal}
        if(numbers.any{it<0}) throw new IllegalArgumentException()
        if(op=='between' && (!upper || (upper as BigDecimal)<numbers[0])) throw new IllegalArgumentException()
    } else if(type=='PctDayOfWeek') {
        def dayMap=[MONDAY:'MON',TUESDAY:'TUE',WEDNESDAY:'WED',THURSDAY:'THU',FRIDAY:'FRI',SATURDAY:'SAT',SUNDAY:'SUN','1':'MON','2':'TUE','3':'WED','4':'THU','5':'FRI','6':'SAT','7':'SUN']
        def days=tokens.collect{def day=it.toUpperCase(java.util.Locale.ROOT);dayMap[day] ?: day}
        if(days.any{!(it in ['MON','TUE','WED','THU','FRI','SAT','SUN'])}) throw new IllegalArgumentException()
        value=days.join(',')
    } else if(type=='PctTimeRange') {
        def parts=value.split('-',-1)
        if(parts.length!=2) throw new IllegalArgumentException()
        def from=java.time.LocalTime.parse(parts[0].trim()), thru=java.time.LocalTime.parse(parts[1].trim())
        value=from.toString()+'-'+thru.toString()
    } else if(type in ['PctProduct','PctProductCategory','PctCustomerGroup']) {
        def refs=op=='in' ? tokens : [value]
        def metadata=[PctProduct:['mantle.product.Product','productId','ownerPartyId'],PctProductCategory:['mantle.product.category.ProductCategory','productCategoryId',null],PctCustomerGroup:['zenith.erp.contacts.CustomerGroup','customerGroupId','organizationPartyId']][type]
        for(id in refs) {
            def row=ec.entity.find(metadata[0]).condition(metadata[1],id).disableAuthz().one()
            if(!row || (metadata[2] && row.get(metadata[2])!=organizationPartyId)) throw new IllegalArgumentException()
        }
    }
    fields=[conditionTypeEnumId:type,operator:op,fieldValue:value,fieldValueTo:op=='between' ? upper : null];valid=true
} catch(Exception ignored) {ec.message.addError('Choose a supported condition/operator, complete nonnegative numeric range, weekday, time range or an existing reference in this organization.')}

def validated=[]
for(cond in (conditions ?: [])) {
    if(!(cond instanceof Map)){ec.message.addError('Each condition must contain typed fields.');return}
    def result=ec.service.sync().name('zenith.pricing.RuleServices.validate#RuleCondition').parameters([organizationPartyId:scope.organizationPartyId,values:cond]).call()
    if(!result.valid || ec.message.hasError()) return
    validated.add(result.fields)
}
def created=ec.entity.makeValue('zenith.erp.pricing.PricingRule').setAll(header.fields+[organizationPartyId:scope.organizationPartyId]).setSequencedIdPrimary().create()
pricingRuleId=created.pricingRuleId
validated.each {ec.entity.makeValue('zenith.erp.pricing.PricingRuleCondition').setAll(it+[pricingRuleId:pricingRuleId]).setSequencedIdPrimary().create()}

if(changes.containsKey('organizationPartyId') && changes.organizationPartyId!=access.rule.organizationPartyId){ec.message.addError('A pricing rule owner cannot be changed.');return}
def editable=['ruleName','description','priority','isActive','isStackable','validFromDate','validThruDate','actionType','actionValue','maxDiscount','minimumPrice']
// Disabling a legacy invalid rule must remain possible without applying its action.
if(changes.isActive=='N' && editable.findAll{changes.containsKey(it)}==['isActive']) {
    def stored=ec.entity.find('zenith.erp.pricing.PricingRule').condition('pricingRuleId',pricingRuleId).forUpdate(true).one()
    if(!stored || stored.organizationPartyId!=access.rule.organizationPartyId){ec.message.addError('Pricing rule changed; refresh before updating.');return}
    stored.isActive='N';stored.update();return
}
def values=[:]+access.rule
editable.each{if(changes.containsKey(it)) values[it]=changes[it]}
def validated=ec.service.sync().name('zenith.pricing.RuleServices.validate#RuleHeader').parameters([values:values]).call()
if(!validated.valid || ec.message.hasError()) return
if(validated.fields.isActive=='Y') {
    for(condition in ec.entity.find('zenith.erp.pricing.PricingRuleCondition').condition('pricingRuleId',pricingRuleId).list()) {
        def check=ec.service.sync().name('zenith.pricing.RuleServices.validate#RuleCondition').parameters([organizationPartyId:access.rule.organizationPartyId,values:condition]).call()
        if(!check.valid || ec.message.hasError()) return
    }
}
def stored=ec.entity.find('zenith.erp.pricing.PricingRule').condition('pricingRuleId',pricingRuleId).forUpdate(true).one()
if(!stored || stored.organizationPartyId!=access.rule.organizationPartyId){ec.message.addError('Pricing rule changed; refresh before updating.');return}
stored.setAll(validated.fields);stored.update()
